css:
.loader {
  position: relative;
  width: 96px;
  height: 96px;
  background: transparent;
  border-radius: 100%;
  border: 1px solid #dbdfe3;
  display: flex;
  align-items: center;
  justify-content: center;
  overflow: hidden;
}

.loader::before {
  content: "";
  position: absolute;
  inset: 12px;
  background: transparent;
  border: 0.5px dashed #d7dce2;
  border-radius: 100%;
  box-shadow: inset -2px -2px 12px #e1e3eb, inset 2px 2px 12px #e1e3eb;
}

.loader::after {
  content: "";
  position: absolute;
  width: 32px;
  height: 32px;
  border-radius: 100%;
  border: 0.5px dashed #d7dce2;
  box-shadow: inset -2px -2px 12px #e1e3eb, inset 2px 2px 12px #e1e3eb;
}

.loader span {
  position: absolute;
  top: 50%;
  left: 50%;
  width: 50%;
  height: 100%;
  background: transparent;
  transform-origin: top left;
  animation: radar81 2s linear infinite;
  border-top: 1px dashed #6e8298;
}

.loader span::before {
  content: "";
  position: absolute;
  top: 0;
  left: 0;
  width: 100%;
  height: 100%;
  background: #86b1e6;
  transform-origin: top left;
  transform: rotate(-55deg);
  filter: blur(20px);
}

@keyframes radar81 {
  0% {
    transform: rotate(0deg);
  }

  100% {
    transform: rotate(360deg);
  }
}
